package weightedSum

import "sort"

func weightedSum(parent []int, nums []int) int64 {
	height := 1
	tree := make(map[int]int)
	// 初始化所有节点为 -2，表示还未计算
	for i := range parent {
		tree[i] = -2
	}
	tree[0] = 1

	// 收集第一轮无法处理的节点（父节点还未就绪）
	var pending []int
	for i := 1; i < len(parent); i++ {
		l := tree[parent[i]]
		if l == -2 {
			pending = append(pending, i)
			continue
		}
		tree[i] = l + 1
		if l+1 > height {
			height = l + 1
		}
	}

	// 按父节点的深度升序排序，保证修复时父节点已经就绪
	sort.Slice(pending, func(a, b int) bool {
		return tree[parent[pending[a]]] < tree[parent[pending[b]]]
	})

	// 一次遍历修复
	for _, k := range pending {
		tree[k] = tree[parent[k]] + 1
		if tree[k] > height {
			height = tree[k]
		}
	}

	res := int64(0)
	for k, v := range tree {
		res += int64(nums[k] * (height - v + 1))
	}

	return res
}

package weightedSum

func weightedSum(parent []int, nums []int) int64 {
	n := len(parent)
	depth := make([]int, n)
	children := make([][]int, n)

	// 建立子节点列表
	for i := 1; i < n; i++ {
		children[parent[i]] = append(children[parent[i]], i)
	}

	// BFS 计算每个节点的深度（从 1 开始）
	depth[0] = 1
	maxDepth := 1
	queue := []int{0}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, child := range children[cur] {
			depth[child] = depth[cur] + 1
			if depth[child] > maxDepth {
				maxDepth = depth[child]
			}
			queue = append(queue, child)
		}
	}

	res := int64(0)
	for i := 0; i < n; i++ {
		res += int64(nums[i]) * int64(maxDepth-depth[i]+1)
	}
	return res
}
